/// Publishes a broadcast response, routing to depth or quote subjects.
void publish(
  BroadcastResponse2 response, {
  required bool depth,
  required bool isTBTDepth,
}) {
  if (depth) {
    _depthSubject.add(response);
  } else if (isTBTDepth) {
    _depthTBTSubject.add(response);
    // Uncomment below line if u want to update LPT , High , Low ..etc from
    // TBT broadcaster
    _quoteSubject.add(response);
  } else {
    _quoteSubject.add(response);
  }
}

